package com.northstar.crm.service;

import com.northstar.crm.domain.*;import com.northstar.crm.repo.*;import com.northstar.crm.security.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import org.springframework.web.client.RestClient;import java.io.*;import java.nio.file.*;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Service public class DocumentService {
 public record Download(String filename,String contentType,long size,InputStream stream){}
 private static final long MAX_SIZE=10*1024*1024;private static final Set<String> TYPES=Set.of("application/pdf","text/plain","text/csv","application/vnd.openxmlformats-officedocument.wordprocessingml.document");
 private final DocumentRepository documents;private final OrganizationService organizations;private final ActorResolver actors;private final AccessPolicy access;private final AuditService audit;private final Path base;private final RestClient http;
 public DocumentService(DocumentRepository d,OrganizationService o,ActorResolver a,AccessPolicy p,AuditService audit,RestClient.Builder client,@Value("${app.storage-path}")String path)throws IOException{documents=d;organizations=o;actors=a;access=p;this.audit=audit;this.http=client.build();base=Path.of(path).toAbsolutePath().normalize();Files.createDirectories(base);}
 @Transactional(readOnly=true) public List<CustomerDocument> forOrganization(UUID orgId){var actor=actors.current();organizations.getAuthorized(orgId);return actor.getRole()==Role.CUSTOMER_CONTACT?documents.findByOrganizationIdAndVisibilityOrderByCreatedAtDesc(orgId,Visibility.CUSTOMER_VISIBLE):documents.findByOrganizationIdOrderByCreatedAtDesc(orgId);}
 @Transactional public CustomerDocument upload(UUID orgId,String filename,String contentType,byte[] bytes,DocumentCategory category,Visibility visibility,String tags){var actor=actors.current();var org=organizations.getAuthorized(orgId);if(actor.getRole()==Role.CUSTOMER_CONTACT)throw new org.springframework.security.access.AccessDeniedException("Staff upload required");access.requireDocument(actor,newTransient(orgId,visibility));if(bytes==null||bytes.length==0||bytes.length>MAX_SIZE)throw new IllegalArgumentException("File must be between 1 byte and 10 MB");if(!TYPES.contains(contentType))throw new IllegalArgumentException("File type not allowed");var clean=StringUtils.cleanPath(Optional.ofNullable(filename).orElse("document"));if(clean.contains("..")||clean.contains("/")||clean.contains("\\")||clean.length()>180)throw new IllegalArgumentException("Invalid filename");var stored=UUID.randomUUID().toString()+extension(clean);var target=resolveStored(stored);try{Files.write(target,bytes,StandardOpenOption.CREATE_NEW);}catch(IOException e){throw new UncheckedIOException("Could not store document",e);}var doc=documents.save(new CustomerDocument(orgId,actor.getId(),clean,stored,contentType,bytes.length,category,visibility,cleanTags(tags)));audit.record(actor,"DOCUMENT_UPLOADED","Document",doc.getId(),"{}","name="+clean+",visibility="+visibility,"authorized organization scope");return doc;}
 /** Import a document straight from the source system's link instead of downloading and re-uploading it. */
 @Transactional public CustomerDocument importFromUrl(UUID orgId,String sourceUrl,String filename,DocumentCategory category,Visibility visibility,String tags){
  var actor=actors.current();organizations.getAuthorized(orgId);
  if(actor.getRole()==Role.CUSTOMER_CONTACT)throw new org.springframework.security.access.AccessDeniedException("Staff import required");
  access.requireDocument(actor,newTransient(orgId,visibility));
  if(sourceUrl==null||!sourceUrl.startsWith("http")||sourceUrl.length()>2000)throw new IllegalArgumentException("Enter an http(s) source link under 2,000 characters");
  var clean=StringUtils.cleanPath(Optional.ofNullable(filename).filter(f->!f.isBlank()).orElse("imported-document.pdf"));
  if(clean.contains("..")||clean.contains("/")||clean.contains("\\")||clean.length()>180)throw new IllegalArgumentException("Invalid filename");
  var contentType=switch(extension(clean)){case ".pdf"->"application/pdf";case ".txt"->"text/plain";case ".csv"->"text/csv";default->throw new IllegalArgumentException("File type not allowed");};
  byte[] bytes=http.get().uri(sourceUrl).retrieve().body(byte[].class);
  if(bytes==null||bytes.length==0||bytes.length>MAX_SIZE)throw new IllegalArgumentException("Imported file must be between 1 byte and 10 MB");
  var stored=UUID.randomUUID().toString()+extension(clean);
  try{Files.write(resolveStored(stored),bytes,StandardOpenOption.CREATE_NEW);}catch(IOException e){throw new UncheckedIOException("Could not store document",e);}
  var doc=documents.save(new CustomerDocument(orgId,actor.getId(),clean,stored,contentType,bytes.length,category,visibility,cleanTags(tags)));
  audit.record(actor,"DOCUMENT_IMPORTED","Document",doc.getId(),"{}","name="+clean+",bytes="+bytes.length,"authorized organization scope");
  return doc;
 }
 /** Stage the partner's signed packet under the delivered file name before filing it against the account. */
 @Transactional public CustomerDocument stagePartnerPacket(UUID orgId,String fileName,byte[] bytes,DocumentCategory category,Visibility visibility,String tags){var actor=actors.current();organizations.getAuthorized(orgId);if(actor.getRole()==Role.CUSTOMER_CONTACT)throw new org.springframework.security.access.AccessDeniedException("Staff file required");access.requireDocument(actor,newTransient(orgId,visibility));if(bytes==null||bytes.length==0||bytes.length>MAX_SIZE)throw new IllegalArgumentException("Packet must be between 1 byte and 10 MB");var pktDir=base.resolve("packets");try{Files.createDirectories(pktDir);try(var out=Files.newOutputStream(pktDir.resolve(fileName),StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING)){out.write(bytes);}}catch(IOException e){throw new UncheckedIOException("Could not stage the packet",e);}var stored=UUID.randomUUID().toString()+extension(Optional.ofNullable(fileName).orElse("packet"));try{Files.write(resolveStored(stored),bytes,StandardOpenOption.CREATE_NEW);}catch(IOException e){throw new UncheckedIOException("Could not store the packet",e);}var doc=documents.save(new CustomerDocument(orgId,actor.getId(),Optional.ofNullable(fileName).orElse("packet"),stored,"application/octet-stream",bytes.length,category,visibility,Optional.ofNullable(tags).orElse("")));audit.record(actor,"PARTNER_PACKET_FILED","Document",doc.getId(),"{}","file="+fileName+",bytes="+bytes.length,"authorized organization scope");return doc;}
 @Transactional public Download download(UUID id){var actor=actors.current();var doc=documents.findById(id).orElseThrow(()->new NoSuchElementException("Document not found"));organizations.getAuthorized(doc.getOrganizationId());access.requireDocument(actor,doc);try{var path=resolveStored(doc.getStoredName());var stream=Files.newInputStream(path,StandardOpenOption.READ);audit.record(actor,"DOCUMENT_DOWNLOADED","Document",id,"{}","bytes="+doc.getSizeBytes(),"organization scope and visibility="+doc.getVisibility());return new Download(doc.getDisplayName(),doc.getContentType(),doc.getSizeBytes(),stream);}catch(IOException e){throw new UncheckedIOException("Document content unavailable",e);}}
 @Transactional public void delete(UUID id){var actor=actors.current();var doc=documents.findById(id).orElseThrow();var org=organizations.getAuthorized(doc.getOrganizationId());access.requireManageOrganization(actor,org);documents.delete(doc);try{Files.deleteIfExists(resolveStored(doc.getStoredName()));}catch(IOException e){throw new UncheckedIOException(e);}audit.record(actor,"DOCUMENT_DELETED","Document",id,"name="+doc.getDisplayName(),"{}","organization owner or admin");}
 /** Canonicalized base-directory check is intentional and must remain on every download. */
 private Path resolveStored(String stored){try{var canonicalBase=base.toFile().getCanonicalFile().toPath();var candidate=canonicalBase.resolve(stored).normalize().toFile().getCanonicalFile().toPath();if(!candidate.startsWith(canonicalBase)||candidate.equals(canonicalBase))throw new SecurityException("Invalid storage path");return candidate;}catch(IOException e){throw new UncheckedIOException(e);}}
 private String extension(String n){int i=n.lastIndexOf('.');return i<0?"":n.substring(i).toLowerCase();}private String cleanTags(String tags){if(tags==null)return "";var t=tags.strip();if(t.length()>300)throw new IllegalArgumentException("Tags too long");return t;}
 private CustomerDocument newTransient(UUID org,Visibility v){return new CustomerDocument(org,UUID.randomUUID(),"check","check","text/plain",1,DocumentCategory.ONBOARDING,v,"");}
}
